const cfg = $('Configuration').first().json;
const debut = $now.minus({ months: 1 }).startOf('month'); const fin = debut.endOf('month');
const libelleMois = debut.setLocale('fr').toFormat('LLLL yyyy');
const noms = {}; for (const w of $('Lire les workflows').all()) noms[w.json.id] = w.json.name;
const minutesPar = {};
for (const ligne of String(cfg.minutes_par_workflow || '').split('\n')) { const [nom, min] = ligne.split('|').map(s => (s || '').trim()); if (nom && Number(min) > 0) minutesPar[nom.toLowerCase()] = Number(min); }
const parWf = {};
for (const e of $('Lire les exécutions réussies').all().map(i => i.json)) {
  if (!e.startedAt || e.mode === 'manual') continue;
  const t = DateTime.fromISO(e.startedAt); if (t < debut || t > fin) continue;
  const nom = noms[e.workflowId] || ('Workflow ' + e.workflowId);
  parWf[nom] = (parWf[nom] || 0) + 1;
}
const lignes = Object.entries(parWf).map(([nom, n]) => { const m = minutesPar[nom.toLowerCase()] ?? Number(cfg.minutes_par_defaut || 0); return { nom, executions: n, minutes: n * m }; }).sort((a, b) => b.minutes - a.minutes);
const totalExec = lignes.reduce((s, l) => s + l.executions, 0);
const heures = Math.round(lignes.reduce((s, l) => s + l.minutes, 0) / 6) / 10;
const valeur = Math.round(heures * Number(cfg.taux_horaire || 0));
const fmt = n => String(n).replace('.', ',');
const tr = lignes.slice(0, 10).map(l => '<tr><td style="padding:6px 10px;border-bottom:1px solid #eee">' + l.nom + '</td><td style="padding:6px 10px;border-bottom:1px solid #eee;text-align:right">' + l.executions + '</td><td style="padding:6px 10px;border-bottom:1px solid #eee;text-align:right">' + fmt(Math.round(l.minutes / 6) / 10) + ' h</td></tr>').join('');
const html = '<p>Bonjour,</p><p>En ' + libelleMois + ', les automatisations ont tourné <b>' + totalExec + ' fois</b> et ont évité environ <b>' + fmt(heures) + ' heures</b> de travail manuel, soit <b>' + valeur + ' €</b> au taux de ' + cfg.taux_horaire + ' € de l\'heure.</p>' + (tr ? '<table style="border-collapse:collapse;font-size:14px"><tr><th style="text-align:left;padding:6px 10px">Workflow</th><th style="text-align:right;padding:6px 10px">Exécutions</th><th style="text-align:right;padding:6px 10px">Temps gagné</th></tr>' + tr + '</table>' : '<p>Aucune exécution automatique ce mois-ci.</p>') + '<p>Les minutes gagnées par exécution se règlent dans le nœud Configuration.</p>';
return [{ json: { mois: libelleMois, executions: totalExec, heures, valeur_euros: valeur, detail: JSON.stringify(lignes), objet: 'Temps gagné en ' + libelleMois + ' : ' + fmt(heures) + ' h', html } }];
